create table if not exists meals (
  id          bigint primary key,
  name        text not null,
  description text,
  category    text check (category in ('Breakfast','Lunch','Snack','Dinner')),
  is_veg      boolean default true,
  hair_benefit text,
  image_url   text,
  data_source text
);

create table if not exists meal_nutrients (
  id              bigint primary key generated always as identity,
  meal_id         bigint references meals(id) on delete cascade,
  protein_g       float4,
  iron_mg         float4,
  vitamin_d_iu    float4,
  vitamin_c_mg    float4,
  zinc_mg         float4,
  omega3_g        float4,
  vitamin_b12_mcg float4,
  biotin_mcg      float4,
  vitamin_e_mg    float4,
  selenium_mcg    float4,
  niacin_mg       float4
);

